import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.CuUVYbLV.js";const b=JSON.parse('{"title":"目录结构","description":"角色目录、全局目录与 .rolebox 状态目录各放什么，附一份「我该把文件放哪」的决策表和排查索引","frontmatter":{"title":"目录结构","description":"角色目录、全局目录与 .rolebox 状态目录各放什么，附一份「我该把文件放哪」的决策表和排查索引"},"headers":[],"relativePath":"01-Overview/directory-structure.md","filePath":"01-Overview/directory-structure.md"}'),s={name:"01-Overview/directory-structure.md"};function l(n,e,c,r,i,p){return t(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="目录结构-directory-structure" tabindex="-1">目录结构（Directory Structure） <a class="header-anchor" href="#目录结构-directory-structure" aria-label="Permalink to &quot;目录结构（Directory Structure）&quot;">​</a></h1><p>rolebox 用一组约定目录组织角色及其资源：每个角色一份目录，技能、函数、引用、子代理各有位置，运行时按约定路径自动加载。本页只讲读者要打交道的目录——每个目录放什么、放错会怎样、出问题时该看哪里。</p><blockquote><p>前置：<a href="/rolebox-docs/02-Guide/create-a-role.html">创建角色</a>｜相关：<a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a>、<a href="/rolebox-docs/02-Guide/skills.html">技能系统</a>、<a href="/rolebox-docs/02-Guide/functions.html">函数系统</a>、<a href="/rolebox-docs/02-Guide/references.html">引用文档</a>、<a href="/rolebox-docs/02-Guide/subagents.html">子代理</a></p></blockquote><h2 id="角色根目录与角色目录" tabindex="-1">角色根目录与角色目录 <a class="header-anchor" href="#角色根目录与角色目录" aria-label="Permalink to &quot;角色根目录与角色目录&quot;">​</a></h2><p>三个 harness 只在根路径上不同：opencode 是 <code>~/.config/opencode</code>，pi 是 <code>~/.pi/agent</code>，dsh 是 <code>$DSH_HOME</code> 或 <code>~/.dsh</code>。下文以 opencode 取值举例。</p><p>角色根目录的解析顺序是：当前项目下存在 <code>rolebox/</code> 就用它，否则用 <code>{configDir}/rolebox/</code>。<strong>角色 ID 直接取自目录名。</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.config/opencode/</span></span>
<span class="line"><span>├── rolebox/                        # 角色根目录</span></span>
<span class="line"><span>│   ├── code-reviewer/              # 一个角色：角色 ID 就是目录名</span></span>
<span class="line"><span>│   │   ├── role.yaml               # 角色定义（必需）</span></span>
<span class="line"><span>│   │   ├── PROMPT.md               # 提示词文件，由 role.yaml 的 prompt_file 指向</span></span>
<span class="line"><span>│   │   ├── skills/                 # 角色私有技能</span></span>
<span class="line"><span>│   │   │   ├── review-checklist.md # 单文件技能</span></span>
<span class="line"><span>│   │   │   └── style-check/</span></span>
<span class="line"><span>│   │   │       ├── SKILL.md        # 目录型技能的入口</span></span>
<span class="line"><span>│   │   │       └── references/     # 技能级引用文档</span></span>
<span class="line"><span>│   │   │           └── rules.md</span></span>
<span class="line"><span>│   │   ├── functions/              # 角色私有函数</span></span>
<span class="line"><span>│   │   │   └── security-scan.md</span></span>
<span class="line"><span>│   │   ├── references/             # 角色级引用文档（自动发现）</span></span>
<span class="line"><span>│   │   │   └── style-guide.md</span></span>
<span class="line"><span>│   │   └── subagents/              # 文件式子代理</span></span>
<span class="line"><span>│   │       └── researcher/</span></span>
<span class="line"><span>│   │           ├── role.yaml       # 子代理自己的定义</span></span>
<span class="line"><span>│   │           ├── skills/</span></span>
<span class="line"><span>│   │           └── functions/</span></span>
<span class="line"><span>│   └── team-lead/</span></span>
<span class="line"><span>│       └── role.yaml</span></span>
<span class="line"><span>├── skills/                         # 全局技能目录，所有角色可共享</span></span>
<span class="line"><span>└── functions/                      # 全局函数目录，对所有角色可见</span></span></code></pre></div><p>角色目录里只有 <code>role.yaml</code> 是必需的，其余目录按需创建。</p><h2 id="我该把文件放哪" tabindex="-1">我该把文件放哪 <a class="header-anchor" href="#我该把文件放哪" aria-label="Permalink to &quot;我该把文件放哪&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我想做的事</th><th>放在哪里</th><th>备注</th></tr></thead><tbody><tr><td>定义一个新角色</td><td><code>{roleRoot}/&lt;roleId&gt;/role.yaml</code></td><td>角色 ID = 目录名，不能含 <code>--</code>（它是子代理 ID 的分隔符）</td></tr><tr><td>写角色的系统提示词</td><td>角色目录下的任意 <code>.md</code> + <code>role.yaml</code> 的 <code>prompt_file</code></td><td>也可直接内联在 <code>prompt:</code>；两者都给时以 <code>prompt_file</code> 为准</td></tr><tr><td>加一个只有这个角色能用的技能</td><td><code>&lt;roleDir&gt;/skills/&lt;name&gt;.md</code> 或 <code>&lt;roleDir&gt;/skills/&lt;name&gt;/SKILL.md</code></td><td>同名时目录型技能优先</td></tr><tr><td>加一个所有角色都能用的技能</td><td><code>{configDir}/skills/</code>，在 <code>role.yaml</code> 的 <code>opencode_skills:</code> 里引用</td><td>由 harness 的技能目录提供</td></tr><tr><td>加一个只有这个角色能用的函数</td><td><code>&lt;roleDir&gt;/functions/&lt;name&gt;.md</code></td><td>同名时覆盖全局函数与内置函数</td></tr><tr><td>加一个所有角色都能用的函数</td><td><code>{configDir}/functions/&lt;name&gt;.md</code></td><td>对所有角色可见</td></tr><tr><td>加一份角色常读的知识文档</td><td><code>&lt;roleDir&gt;/references/</code> 下的任意 <code>.md</code></td><td>自动发现；也可在 <code>references:</code> 里显式声明</td></tr><tr><td>加一份只在某个技能里用的知识文档</td><td><code>&lt;skillDir&gt;/references/</code> 下的任意 <code>.md</code></td><td>技能级与角色级引用合并注入</td></tr><tr><td>声明一个子代理</td><td>父角色 <code>role.yaml</code> 的 <code>subagents:</code>，或 <code>&lt;roleDir&gt;/subagents/&lt;name&gt;/role.yaml</code></td><td>文件式子代理可以有自己的 <code>skills/</code> 与 <code>functions/</code></td></tr><tr><td>放项目级运行时配置</td><td>项目根目录的 <code>.rolebox/config.json</code></td><td>例如默认角色，见下节</td></tr><tr><td>放跨会话记忆</td><td>项目根目录的 <code>.rolebox/memory.db</code></td><td>SQLite，由 rolebox 维护，不要手改</td></tr></tbody></table><h2 id="每类文件的加载规则" tabindex="-1">每类文件的加载规则 <a class="header-anchor" href="#每类文件的加载规则" aria-label="Permalink to &quot;每类文件的加载规则&quot;">​</a></h2><h3 id="role-yaml" tabindex="-1">role.yaml <a class="header-anchor" href="#role-yaml" aria-label="Permalink to &quot;role.yaml&quot;">​</a></h3><p>必填 <code>name</code>、<code>description</code>，以及 <code>prompt</code> 与 <code>prompt_file</code> 二选一；完整字段见 <a href="/rolebox-docs/03-Reference/role-yaml.html">role.yaml 参考</a>。角色目录名与子代理的 <code>name</code> 都不能包含 <code>--</code>。</p><h3 id="skills-—-按需加载的技能" tabindex="-1">skills/ — 按需加载的技能 <a class="header-anchor" href="#skills-—-按需加载的技能" aria-label="Permalink to &quot;skills/ — 按需加载的技能&quot;">​</a></h3><p>技能是角色在执行相关任务时才加载的知识模块，可以是一份 Markdown，也可以是一个带 <code>SKILL.md</code> 入口的目录（目录型技能还能再带 <code>references/</code>）。同名时<strong>目录优先于单文件</strong>，四层按顺序取第一个存在的，找不到就不加载（不报错）：</p><ol><li><code>&lt;roleDir&gt;/skills/&lt;name&gt;/SKILL.md</code></li><li><code>&lt;roleDir&gt;/skills/&lt;name&gt;.md</code></li><li><code>{globalSkillsDir}/&lt;name&gt;/SKILL.md</code></li><li><code>{globalSkillsDir}/&lt;name&gt;.md</code></li></ol><p><code>{globalSkillsDir}</code> 随 harness 变化（opencode 是 <code>~/.config/opencode/skills</code>）。用法见<a href="/rolebox-docs/02-Guide/skills.html">技能系统</a>，编写见<a href="/rolebox-docs/02-Guide/authoring-skills.html">编写技能</a>。</p><h3 id="functions-—-用-name-激活的函数" tabindex="-1">functions/ — 用 |name| 激活的函数 <a class="header-anchor" href="#functions-—-用-name-激活的函数" aria-label="Permalink to &quot;functions/ — 用 |name| 激活的函数&quot;">​</a></h3><p>解析顺序与技能同构，按「角色本地 → 全局 → 内置」三层取第一个命中的文件，因此<strong>角色本地函数可以覆盖同名的全局函数或内置函数</strong>：</p><ol><li><code>&lt;roleDir&gt;/functions/&lt;name&gt;.md</code></li><li><code>{configDir}/functions/&lt;name&gt;.md</code></li><li>rolebox 包内置的 <code>functions/&lt;name&gt;.md</code>（<code>plan</code>、<code>execute</code>、<code>loop</code>）</li></ol><p>内置函数默认启用；<code>role.yaml</code> 的 <code>functions:</code> 是合并语义，要移除内置函数得用 <code>disable_functions</code>。见<a href="/rolebox-docs/02-Guide/functions.html">函数系统</a>。</p><h3 id="references-—-被动阅读的知识文档" tabindex="-1">references/ — 被动阅读的知识文档 <a class="header-anchor" href="#references-—-被动阅读的知识文档" aria-label="Permalink to &quot;references/ — 被动阅读的知识文档&quot;">​</a></h3><p>引用文档只有两个层级，<strong>没有全局目录</strong>：角色级 <code>&lt;roleDir&gt;/references/</code> 与技能级 <code>&lt;skillDir&gt;/references/</code>。两个层级都是「目录自动发现 + 显式声明」的合并，而不是优先级屏蔽：目录下（含子目录）的 <code>.md</code> 全部被发现，<code>references:</code> 里同名文件的显式条目只用来覆盖描述信息、或指向目录之外的文件。子代理还会继承父角色的角色级引用。见<a href="/rolebox-docs/02-Guide/references.html">引用文档</a>。</p><h3 id="subagents-—-文件式子代理" tabindex="-1">subagents/ — 文件式子代理 <a class="header-anchor" href="#subagents-—-文件式子代理" aria-label="Permalink to &quot;subagents/ — 文件式子代理&quot;">​</a></h3><p><code>subagents/&lt;name&gt;/role.yaml</code> 会被自动发现，递归深度上限为 3 层（父 → 子 → 孙）。文件式子代理有自己的目录，因而可以有自己的 <code>skills/</code>、<code>functions/</code> 与 <code>references/</code>；内联声明的子代理没有独立目录，它的技能与函数从父角色目录解析。命名、继承与排错见<a href="/rolebox-docs/02-Guide/subagents.html">子代理</a>。</p><h2 id="rolebox-—-项目级运行时目录" tabindex="-1">.rolebox/ — 项目级运行时目录 <a class="header-anchor" href="#rolebox-—-项目级运行时目录" aria-label="Permalink to &quot;.rolebox/ — 项目级运行时目录&quot;">​</a></h2><p>rolebox 在项目根目录维护一个隐藏的 <code>.rolebox/</code> 目录，存放运行时状态、持久化数据与日志。它由 rolebox 自动管理，<strong>不建议手动编辑</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的项目/</span></span>
<span class="line"><span>└── .rolebox/</span></span>
<span class="line"><span>    ├── memory.db         # SQLite 记忆库，存放跨会话、跨角色的记忆条目</span></span>
<span class="line"><span>    ├── config.json       # 项目级配置，例如 { &quot;defaultRole&quot;: &quot;code-reviewer&quot; }</span></span>
<span class="line"><span>    ├── logs/rolebox.log  # 项目本地日志</span></span>
<span class="line"><span>    └── state/            # 运行时状态</span></span>
<span class="line"><span>        ├── engine-*.json          # 图执行状态（节点生命周期、预算）</span></span>
<span class="line"><span>        ├── graph-events-*.ndjson  # 图引擎事件日志（追加式）</span></span>
<span class="line"><span>        ├── loops-*.json           # 循环协调器状态</span></span>
<span class="line"><span>        ├── dispatch-*.json        # 调度任务状态（任务图、结果引用、出站通知）</span></span>
<span class="line"><span>        ├── fnstate-*.json         # 函数状态机（阶段、门控、证据）</span></span>
<span class="line"><span>        ├── metrics-*.json         # 指标快照</span></span>
<span class="line"><span>        ├── signalledger-*.json    # 会话级信号账本</span></span>
<span class="line"><span>        ├── progress/              # 进度报告</span></span>
<span class="line"><span>        ├── checkpoints/           # 失败重试用的进度快照</span></span>
<span class="line"><span>        └── results/               # 溢出到侧车文件的任务结果</span></span></code></pre></div><ul><li>文件名里的短哈希由项目路径规范化后算出，同一个物理目录总是映射到同一组文件名。</li><li>状态文件采用「先写临时文件、再改名覆盖」的原子写入，写到一半崩溃不会留下半个文件。</li><li>启动时会清理超过 7 天未修改的 <code>dispatch-*.json</code> 与对应 <code>.lock</code> 文件；保留天数用环境变量 <code>ROLEBOX_STATE_RETENTION_DAYS</code> 调整。</li><li><code>.rolebox/config.json</code> 在角色解析之后、会话启动之前应用，所以它不影响 <code>rolebox list</code> 的输出，只影响新会话默认选哪个角色。</li><li><code>.rolebox/state/</code> 可以整体删除，rolebox 下次启动会自动重建；删除前先确认 <code>.rolebox/memory.db</code> 里没有要保留的记忆。</li><li>项目级配置与角色安装配置分工不同：<code>.rolebox/config.json</code> 管本项目的运行时行为，<code>~/.config/rolebox/config.yaml</code> 管角色的安装与注册中心。</li></ul><p>状态文件用 <code>rolebox monitor</code> 查看：<code>--task-id=&lt;id&gt;</code> 看单个任务详情，<code>--json</code> 输出机器可读格式，全部参数见 <code>rolebox monitor --help</code>。注意 opencode 上的图引擎完全在内存中运行，状态不落盘、也没有崩溃恢复扫描——图状态要用 <code>graph_status</code> 查询，而不是找文件。</p><h3 id="状态的旧位置-v0-12-0-之前" tabindex="-1">状态的旧位置（v0.12.0 之前） <a class="header-anchor" href="#状态的旧位置-v0-12-0-之前" aria-label="Permalink to &quot;状态的旧位置（v0.12.0 之前）&quot;">​</a></h3><p>v0.12.0 之前，调度与图状态存放在 <code>~/.local/share/rolebox/state/</code>；从 v0.12.0 起改为项目本地的 <code>.rolebox/state/</code>。如果你在新位置看不到文件、而旧位置有残留，删除旧位置的文件是安全的——当前版本只读项目本地这一份。</p><h2 id="rolebox-自己的配置与数据目录" tabindex="-1">rolebox 自己的配置与数据目录 <a class="header-anchor" href="#rolebox-自己的配置与数据目录" aria-label="Permalink to &quot;rolebox 自己的配置与数据目录&quot;">​</a></h2><p>除 harness 的配置目录外，rolebox 在下面两处维护与 harness 无关的配置和数据：</p><table tabindex="0"><thead><tr><th>路径</th><th>内容</th><th>能删吗</th></tr></thead><tbody><tr><td><code>~/.config/rolebox/config.yaml</code></td><td>注册中心列表，默认含 <code>oh-my-role</code></td><td>删除后下次使用会自动重建默认配置</td></tr><tr><td><code>~/.config/rolebox/rolebox.lock</code></td><td>已安装角色的版本、来源与完整性哈希</td><td>删除后角色仍在，但 <code>rolebox sync</code> 找不到它们</td></tr><tr><td><code>~/.config/rolebox/logs/rolebox.log</code></td><td>CLI 操作日志</td><td>可安全删除，自动轮转</td></tr><tr><td><code>~/.local/share/rolebox/roles/</code></td><td>已安装角色包</td><td>交给 <code>rolebox install</code> / <code>rolebox uninstall</code> 管理</td></tr><tr><td><code>~/.local/share/rolebox/cache/</code></td><td>注册中心清单缓存</td><td>可删；默认缓存 5 分钟，<code>--no-cache</code> 跳过</td></tr></tbody></table><p>配置目录的解析顺序是 <code>ROLEBOX_CONFIG_DIR</code> → <code>XDG_CONFIG_HOME/rolebox</code> → <code>%APPDATA%/rolebox</code>（Windows）→ <code>~/.config/rolebox</code>；数据目录同理，依次为 <code>ROLEBOX_DATA_DIR</code> → <code>XDG_DATA_HOME/rolebox</code> → <code>%LOCALAPPDATA%/rolebox</code> → <code>~/.local/share/rolebox</code>。</p><h2 id="出问题时该看哪个目录" tabindex="-1">出问题时该看哪个目录 <a class="header-anchor" href="#出问题时该看哪个目录" aria-label="Permalink to &quot;出问题时该看哪个目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>先看哪里</th><th>怎么查</th></tr></thead><tbody><tr><td>角色没按预期响应，技能或函数没加载</td><td><code>role.yaml</code> 与对应的 <code>skills/</code>、<code>functions/</code> 目录</td><td>核对声明里的名字与文件名是否一致</td></tr><tr><td>任务卡住或状态异常</td><td><code>.rolebox/state/dispatch-*.json</code></td><td><code>rolebox monitor --task-id=&lt;id&gt;</code></td></tr><tr><td>函数状态机行为异常</td><td><code>.rolebox/state/fnstate-*.json</code></td><td><code>rolebox monitor</code></td></tr><tr><td>图执行停滞（pi / dsh）</td><td><code>.rolebox/state/engine-*.json</code></td><td><code>rolebox monitor</code>；opencode 上图在内存里，用 <code>graph_status</code> 查</td></tr><tr><td>进度报告丢失或不更新</td><td><code>.rolebox/state/progress/</code></td><td>直接读 JSON，看时间戳是否更新</td></tr><tr><td>角色安装后没生效</td><td><code>{configDir}/rolebox/&lt;roleId&gt;/</code></td><td><code>rolebox sync opencode</code>（或 <code>pi</code> / <code>dsh</code>），确认符号链接存在</td></tr><tr><td>角色版本不匹配</td><td><code>~/.config/rolebox/rolebox.lock</code></td><td><code>rolebox list</code></td></tr><tr><td>注册中心下载失败</td><td><code>~/.local/share/rolebox/cache/</code></td><td><code>rolebox search &lt;role&gt; --no-cache</code></td></tr><tr><td>跨会话记忆丢失</td><td><code>.rolebox/memory.db</code></td><td>检查文件存在且非空</td></tr><tr><td>状态文件损坏，想重置</td><td><code>.rolebox/state/</code></td><td>删除整个目录，rolebox 下次启动重建</td></tr><tr><td>想彻底清理运行时数据</td><td><code>.rolebox/</code></td><td>删除整个目录（<code>memory.db</code> 含记忆，先确认备份）</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/rolebox-docs/02-Guide/create-a-role.html">创建角色</a> — role.yaml 逐字段与三个配方</li><li><a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a> — 三个 harness 的目录、安装与同步对照</li><li><a href="/rolebox-docs/01-Overview/architecture-overview.html">架构概览</a> — 角色从目录到运行时的加载过程</li><li><a href="/rolebox-docs/02-Guide/subagents.html">子代理</a> — 子代理目录、命名与配置继承</li></ul>`,40)])])}const m=o(s,[["render",l]]);export{b as __pageData,m as default};
